const edges=[['token','auth','normal'],['userapi','auth','normal'],['auth','login','normal'],['auth','session','normal'],['auth','test','test'],['api','userapi','normal'],['login','router','normal'],['session','router','normal']];
let selected='auth'; let mode='universe';
const svg=document.getElementById('universe'), edgeG=document.getElementById('edges'), nodeG=document.getElementById('nodes'), labelsG=document.getElementById('clusterLabels');
function svgEl(tag,attrs={}){const n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n}
function renderStars(){const g=document.querySelector('.stars-bg');for(let i=0;i<95;i++){const c=svgEl('circle',{cx:(i*97)%991+4,cy:(i*53)%681+8,r:i%9===0?1.2:.55,fill:i%13===0?'#61E7FF':'#94A4C4'});g.appendChild(c)}}
function renderClusters(){labelsG.innerHTML='';[['AUTH',500,120],['API',280,300],['UI',745,250],['TESTS',650,565],['DOCS',175,115]].forEach(([t,x,y])=>{const n=svgEl('text',{x,y,class:'cluster-label'});n.textContent=t;labelsG.appendChild(n)})}
function nodeClass(k){return k==='core'?'node-core':k==='test'?'node-test':k==='ui'?'node-ui':k==='doc'?'node-doc':'node-file'}
function relatedSet(id,depth=1){const s=new Set([id]);for(let d=0;d<depth;d++){for(const [a,b] of edges){if(s.has(a))s.add(b);if(s.has(b))s.add(a)}}return s}
function impactSet(id){const s=new Set([id]);let changed=true;while(changed){changed=false;for(const [a,b] of edges){if(s.has(a)&&!s.has(b)){s.add(b);changed=true}}}return s}
function renderGraph(){edgeG.innerHTML='';nodeG.innerHTML='';const active=mode==='impact'?impactSet(selected):mode==='focus'?relatedSet(selected,1):new Set(files.map(f=>f.id));edges.forEach(([a,b,t])=>{const A=files.find(f=>f.id===a),B=files.find(f=>f.id===b);const hot=active.has(a)&&active.has(b)&&(mode!=='universe');const line=svgEl('line',{x1:A.x,y1:A.y,x2:B.x,y2:B.y,class:`edge ${t==='test'?'test':''} ${hot?'hot':''}`}); if(mode!=='universe'&&(!active.has(a)||!active.has(b))) line.style.opacity='.05';edgeG.appendChild(line)});
 files.forEach(f=>{const g=svgEl('g',{class:`node-group ${f.id===selected?'selected':''} ${!active.has(f.id)?'dim':''}`,'data-id':f.id});const halo=svgEl('circle',{cx:f.x,cy:f.y,r:f.r+10,class:'halo'});const c=svgEl('circle',{cx:f.x,cy:f.y,r:f.r,class:nodeClass(f.kind)});c.setAttribute('filter',f.id===selected?'url(#glow)':'');const label=svgEl('text',{x:f.x+f.r+9,y:f.y+4,class:'node-label'});label.textContent=f.name;g.append(halo,c,label);g.addEventListener('click',()=>selectFile(f.id,true));nodeG.appendChild(g)})}
function selectFile(id,setFocus=false){selected=id; if(setFocus&&mode==='universe') mode='focus';document.querySelectorAll('.segmented button').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));const f=files.find(x=>x.id===id);document.getElementById('fileName').textContent=f.name;document.getElementById('filePath').textContent=f.path;document.getElementById('filePurpose').textContent=f.purpose;document.getElementById('loc').textContent=f.loc;document.getElementById('inbound').textContent=f.inbound;document.getElementById('outbound').textContent=f.outbound;document.getElementById('symbols').innerHTML=f.symbols.map(s=>`<span class="chip">${s}</span>`).join('')||'<span class="chip">No exported symbols</span>';document.getElementById('depends').innerHTML=f.depends.map(s=>`<li>${s}</li>`).join('')||'<li>None detected</li>';document.getElementById('usedBy').innerHTML=f.usedBy.map(s=>`<li>${s}</li>`).join('')||'<li>None detected</li>';document.getElementById('changeTitle').textContent=f.change;renderGraph()}
function setMode(m){mode=m;document.querySelectorAll('.segmented button').forEach(b=>b.classList.toggle('selected',b.dataset.mode===m));renderGraph()}
document.querySelectorAll('.segmented button').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));document.getElementById('impactButton').addEventListener('click',()=>setMode('impact'));
const palette=document.getElementById('palette'),input=document.getElementById('searchInput'),results=document.getElementById('searchResults');function openPalette(){palette.classList.remove('hidden');input.value='';renderResults('');setTimeout(()=>input.focus(),20)}function closePalette(){palette.classList.add('hidden')}function renderResults(q){const matches=files.filter(f=>(f.name+' '+f.path+' '+f.symbols.join(' ')+' '+f.purpose).toLowerCase().includes(q.toLowerCase())).slice(0,7);results.innerHTML=matches.map(f=>`<div class="result" data-id="${f.id}"><div class="result-icon">${f.kind==='core'?'✦':f.kind==='test'?'◌':'●'}</div><div class="result-main"><strong>${f.name}</strong><small>${f.purpose}</small></div><div class="result-path">${f.path}</div></div>`).join('')||'<div class="result"><div class="result-main"><strong>No results</strong><small>Try a file, symbol, or module name.</small></div></div>';results.querySelectorAll('[data-id]').forEach(r=>r.addEventListener('click',()=>{selectFile(r.dataset.id,true);closePalette()}))}
document.getElementById('searchButton').addEventListener('click',openPalette);input.addEventListener('input',e=>renderResults(e.target.value));palette.addEventListener('click',e=>{if(e.target===palette)closePalette()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}if(e.key==='Escape')closePalette()});
renderStars();renderClusters();selectFile('auth');
